@ScalarOperator(IS_DISTINCT_FROM)
public static boolean isDistinctFrom(
        @SqlType("char(x)") Slice left,
        @IsNull boolean leftNull,
        @SqlType("char(x)") Slice right,
        @IsNull boolean rightNull)
